CREATE OR REPLACE FUNCTION public.publish_monitor_provider_work_finish(p_connection_id uuid, p_lease uuid, p_outcome text, p_error text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c social_connections;
